package com.desktodo.app;
import org.json.*;import java.time.*;import java.util.*;
/** One future occurrence per series; completion and skip share deterministic scheduling. */
final class RepeatRules {
 static final String[] KEYS={"none","daily","weekdays","weekly","monthly"},NAMES={"不重复","每天","周一至周五","每周","每月"};
 static String label(JSONObject t){String key=t.optString("repeatRule","none");for(int i=0;i<KEYS.length;i++)if(KEYS[i].equals(key))return NAMES[i];return "未知规则";}
 static JSONObject configure(JSONObject task,String rule)throws Exception{if(!Arrays.asList(KEYS).contains(rule))throw new Exception("重复规则不支持");JSONObject t=DeskModel.copy(task);if(rule.equals("none")){for(String k:new String[]{"repeatRule","repeatSeries","repeatDay"})t.remove(k);return t;}if(t.isNull("due")||t.optString("due").isEmpty())throw new Exception("重复事项需要设置截止时间");Instant due=Instant.parse(t.getString("due"));ZonedDateTime at=due.atZone(ScreenData.ZONE);t.put("repeatRule",rule).put("repeatSeries",t.optString("repeatSeries",t.getString("id"))).put("repeatDay",t.optString("repeatRule").equals(task.optString("repeatRule"))?task.optInt("repeatDay",at.getDayOfMonth()):at.getDayOfMonth());return t;}
 static JSONObject next(JSONObject task,Instant now)throws Exception{String rule=task.optString("repeatRule","none");if(rule.equals("none")||rule.isEmpty())return null;if(!Arrays.asList(KEYS).contains(rule))throw new Exception("重复规则不支持");ZonedDateTime at=Instant.parse(task.getString("due")).atZone(ScreenData.ZONE);int anchor=task.optInt("repeatDay",at.getDayOfMonth());if(anchor<1||anchor>31)throw new Exception("重复日期无效");ZonedDateTime cursor=at;int loops=0;do{if(++loops>100000)throw new Exception("重复日期跨度过大，请修改截止时间");switch(rule){case "monthly":YearMonth month=YearMonth.from(cursor).plusMonths(1);cursor=month.atDay(Math.min(anchor,month.lengthOfMonth())).atTime(at.toLocalTime()).atZone(ScreenData.ZONE);break;case "weekly":cursor=cursor.plusWeeks(1);break;default:cursor=cursor.plusDays(1);if(rule.equals("weekdays"))while(cursor.getDayOfWeek().getValue()>5)cursor=cursor.plusDays(1);}}while(!cursor.toInstant().isAfter(now));String series=task.optString("repeatSeries",task.getString("id"));JSONObject next=DeskModel.copy(task).put("id",series+":"+cursor.toLocalDate()).put("due",cursor.toInstant().toString()).put("repeatSeries",series).put("repeatDay",anchor);for(String k:new String[]{"completedAt","deletedAt","recordType","nextID","nextKey"})next.remove(k);return next;}
 static boolean sameDay(String a,String b){try{return Instant.parse(a).atZone(ScreenData.ZONE).toLocalDate().equals(Instant.parse(b).atZone(ScreenData.ZONE).toLocalDate());}catch(Exception e){return false;}}
 static String fingerprint(JSONObject t)throws Exception{String due="";try{due=String.valueOf(Instant.parse(t.getString("due")).getEpochSecond());}catch(Exception ignored){}StringBuilder b=new StringBuilder();for(String value:new String[]{t.optString("id"),t.optString("title"),due,t.optString("repeatRule"),t.optString("repeatSeries"),String.valueOf(t.optInt("repeatDay",0)),t.optBoolean("pinned")?"1":"0"})b.append(value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length).append(':').append(value);return DeskModel.contentKey(b.toString());}
 static final class Result {final JSONArray active;final JSONObject record;Result(JSONArray active,JSONObject record){this.active=active;this.record=record;}}
 static Result finish(JSONArray active,int index,Instant now,boolean skip)throws Exception{if(index<0||index>=active.length())throw new Exception("事项已被移除");JSONObject old=DeskModel.copy(active.getJSONObject(index));JSONObject next=next(old,now);JSONArray out=new JSONArray();for(int i=0;i<active.length();i++)if(i!=index)out.put(active.get(i));if(next!=null){for(int i=0;i<out.length();i++)if(out.getJSONObject(i).getString("id").equals(next.getString("id")))throw new Exception("下一次事项已存在，请先读取设备最新清单");out.put(next);old.put("nextID",next.getString("id")).put("nextKey",fingerprint(next));}old.put("recordType",skip?"skipped":"completed").put("completedAt",now.toString());return new Result(out,old);}
 static JSONArray restore(JSONArray active,JSONObject record)throws Exception{JSONArray out=new JSONArray();String nextID=record.optString("nextID");boolean found=nextID.isEmpty();for(int i=0;i<active.length();i++){JSONObject t=active.getJSONObject(i);if(t.optString("id").equals(record.optString("id")))throw new Exception("此事项已在清单中");if(!nextID.isEmpty()&&t.optString("id").equals(nextID)){if(!fingerprint(t).equals(record.optString("nextKey")))throw new Exception("下一次事项已修改，无法直接撤销，请先核对清单");found=true;}else out.put(t);}if(!found)throw new Exception("下一次事项已被处理，无法直接恢复本次");if(out.length()>=8)throw new Exception("未完成已达八条");JSONObject t=DeskModel.copy(record);for(String k:new String[]{"completedAt","deletedAt","recordType","nextID","nextKey"})t.remove(k);if(t.optBoolean("pinned")&&DeskModel.pins(out)>=3)t.put("pinned",false);out.put(t);return out;}
}
